from timeseries import moving_average

def test_short_series():
    # Passes before fix
    assert moving_average([1.0, 2.0], 3) == []

def test_window_size_one():
    # Window of 1 should equal series
    assert moving_average([1.0, 2.0, 3.0], 1) == [1.0, 2.0, 3.0]

def test_window_two():
    assert moving_average([1.0, 3.0, 5.0, 7.0], 2) == [2.0, 4.0, 6.0]

def test_window_three():
    assert moving_average([10.0, 20.0, 30.0, 40.0], 3) == [20.0, 30.0]

